package catalog

import (
	_ "embed"
	"encoding/json"
)

//go:embed proven.json
var provenJSON []byte

// provenIDs lists templates with a recorded pass on a real engine run. It is
// regenerated by scripts/gen-proven-templates; everything else is a preview.
var provenIDs = func() map[string]bool {
	var ids []string
	if err := json.Unmarshal(provenJSON, &ids); err != nil {
		panic("catalog: proven.json: " + err.Error())
	}
	out := make(map[string]bool, len(ids))
	for _, id := range ids {
		out[id] = true
	}
	return out
}()

// IsProven reports whether the template has a recorded real-engine pass.
func IsProven(id string) bool { return provenIDs[id] }

// IsPreview is true for a catalog template that is installable but has no
// real-engine pass yet.
func IsPreview(id string) bool {
	_, ok := TemplateByID(id)
	return ok && !provenIDs[id]
}

// ProvenCounts returns how many catalog templates are proven and how many are
// still previews.
func ProvenCounts() (proven, preview int) {
	for _, t := range Templates {
		if provenIDs[t.ID] {
			proven++
		} else {
			preview++
		}
	}
	return proven, preview
}
